	}
	if r.match < index {
		r.waitToRetry()
		r.match = index
		return true
	}
	return false
}

func (r *remote) progress(lastIndex uint64) {
	if r.state == remoteReplicate {

		r.next = lastIndex + 1
	} else if r.state == remoteRetry {
